using RealmForge.Domain.Entities;
using RealmForge.Shared.Characters;
using RealmForge.Shared.Enums;
using static RealmForge.Infrastructure.Persistence.Seeding.MagicItemSeeder;

namespace RealmForge.Infrastructure.Persistence.Seeding.MagicItemsData;

///	<summary>
///	Wand of Wonder (2014 ruleset). SRD 5.1 text (CC BY 4.0) in English and in the official Italian SRD 5.1 (CC BY 4.0).
///	</summary>
public static class WandOfWonder2014Seeder
{
	public static IEnumerable<MagicItem> Build()
	{
		yield return Item("wand-of-wonder", null, 0, MagicItemType.Wand, ItemRarity.Rare, true, ContentSource.Srd51,
			Charges(7, ItemRecharge.LongRest, "1d6+1"),
			("Bacchetta delle meraviglie", "Bacchetta, rara (richiede sintonia con un incantatore)",
			"Questa bacchetta possiede 7 cariche. Mentre il personaggio la impugna, può usare un'azione per consumare 1 carica e scegliere un bersaglio entro 36 metri da lui. Il bersaglio può essere una creatura, un oggetto o un punto nello spazio. Tira un d100 e consulta la seguente tabella per scoprire cosa succede.\n\nSe l'effetto fa lanciare al personaggio un incantesimo tramite la bacchetta, la CD del tiro salvezza è pari a 15. Se di norma l'incantesimo ha una gittata espressa in metri, essa diventa di 36 metri, se non lo è già.\n\nSe l'effetto copre una determinata area, l'incantesimo sarà centrato sul bersaglio e lo includerà. Se un effetto può colpire più bersagli, il GM determina in modo casuale quali vengono colpiti.\n\nAll'alba di ogni giorno, la bacchetta recupera 1d6 + 1 cariche consumate. Se il personaggio consuma l'ultima carica, deve tirare un d20: se ottiene 1, la bacchetta si sbriciola ed è distrutta.\n\n| d100 | Effetto |\n|---|---|\n| 01–05 | Il personaggio lancia lentezza. |\n| 06–10 | Il personaggio lancia luminescenza. |\n| 11–15 | Il personaggio è stordito fino all'inizio del suo turno successivo, convinto che sia successo qualcosa di meraviglioso. |\n| 16–20 | Il personaggio lancia folata di vento. |\n| 21–25 | Il personaggio lancia individuazione dei pensieri sul bersaglio scelto. Se non aveva scelto una creatura, il personaggio subisce 1d6 danni psichici. |\n| 26–30 | Il personaggio lancia nube maleodorante. |\n| 31–33 | Una fitta pioggia cade in un'area del raggio di 18 metri centrata sul bersaglio. L'area diventa leggermente oscurata. La pioggia continua a cadere fino all'inizio del turno successivo del personaggio. |\n\n| d100 | Effetto |\n|---|---|\n| 34–36 | Un animale compare nello spazio libero più vicino al bersaglio. L'animale non è sotto il controllo del personaggio e agisce come farebbe normalmente. Tira un d100 per determinare quale animare compare. Con un risultato di 01–25, compare un rinoceronte; con 26–50 compare un elefante; con 51–100 compare un topo. |\n| 37–46 | Il personaggio lancia fulmine. |\n| 47–49 | Una nube di 600 farfalle più grandi del normale riempie un'area del raggio di 9 metri centrata sul bersaglio. L'area diventa pesantemente oscurata. Le farfalle permangono per 10 minuti. |\n| 50–53 | Il personaggio ingrandisce il bersaglio come se avesse lanciato ingrandire/ridurre. Se il bersaglio non può essere influenzato da quell'incantesimo o se il personaggio non ha indicato come bersaglio una creatura, diventa lui stesso il bersaglio dell'incantesimo. |\n| 54–58 | Il personaggio lancia oscurità. |\n| 59–62 | Dal terreno spunta dell'erba in un'area del raggio di 18 metri centrata sul bersaglio. Se l'area era già erbosa, l'erba cresce fino a 10 volte la sua taglia normale e permane in questo stato per 1 minuto. |\n| 63–65 | Un oggetto a scelta del GM scompare e va nel Piano Etereo. L'oggetto non deve essere indossato né trasportato, deve trovarsi entro 36 metri dal bersaglio e non deve superare i 3 metri in nessuna delle sue dimensioni. |\n| 66–69 | Il personaggio si restringe come se avesse lanciato ingrandire/ridurre su se stesso. |\n| 70–79 | Il personaggio lancia palla di fuoco. |\n| 80–84 | Il personaggio lancia invisibilità su se stesso. |\n| 85–87 | Sul bersaglio cresce uno strato di foglie. Se il personaggio ha scelto come bersaglio un punto nello spazio, le foglie spuntano dalla creatura più vicina a quel punto. Se non vengono staccate, le foglie avvizziscono e cadono dopo 24 ore. |\n| 88–90 | La punta della bacchetta genera un getto di 1d4 × 10 gemme, ognuna del valore 1 mo, in una linea lunga 9 metri e larga 1,5 metri. Ogni gemma infligge 1 danno contundente e i danni totali delle gemme vengono divisi equamente tra tutte le creature sulla linea. |\n| 91–95 | Un'esplosione di scintillante luce colorata si estende dal personaggio in un'area del raggio 9 metri. Il personaggio e ogni creatura in grado di vedere che si trovi nell'area devono superare un tiro salvezza su Costituzione con CD 15, altrimenti diventano accecati per 1 minuto. La creatura può ripetere il tiro salvezza alla fine di ogni suo turno e, se lo supera, l'effetto su di essa svanisce. |\n\n| d100 | Effetto |\n|---|---|\n| 96–97 | La pelle del bersaglio diventa di colore azzurro per 1d10 giorni. Se il personaggio ha scelto un punto nello spazio come bersaglio, questo effetto influenza la creatura più vicina a quel punto. |\n| 98–00 | Se il personaggio ha scelto una creatura come bersaglio, essa deve effettuare un tiro salvezza su Costituzione con CD 15. Se non ha scelto una creatura come bersaglio, il personaggio diventa il bersaglio e deve effettuare il tiro salvezza. Se il bersaglio fallisce il tiro salvezza di 5 o più, è pietrificato all'istante. Con ogni altro risultato fallito, il bersaglio è trattenuto e inizia a trasformarsi in pietra. Finché è trattenuto in questo modo, il bersaglio deve ripetere il tiro salvezza alla fine del suo turno successivo: se fallisce, diventa pietrificato, altrimenti l'effetto svanisce. La pietrificazione dura finché il bersaglio non viene liberato dall'incantesimo ristorare superiore o da altre magie analoghe. |"),
			("Wand of Wonder", "Wand, rare (requires attunement by a spellcaster)",
			"This wand has 7 charges. While holding it, you can use an action to expend 1 of its charges and choose a target within 120 feet of you. The target can be a creature, an object, or a point in space. Roll d100 and consult the following table to discover what happens.\n\nIf the effect causes you to cast a spell from the wand, the spell's save DC is 15. If the spell normally has a range expressed in feet, its range becomes 120 feet if it isn't already.\n\nIf an effect covers an area, you must center the spell on and include the target. If an effect has multiple possible subjects, the GM randomly determines which ones are affected.\n\nThe wand regains 1d6 + 1 expended charges daily at dawn. If you expend the wand's last charge, roll a d20. On a 1, the wand crumbles into dust and is destroyed.\n\n| d100 | Effect |\n|---|---|\n| 01-05 | You cast slow. |\n| 06-10 | You cast faerie fire. |\n| 11-15 | You are stunned until the start of your next turn, believing something awesome just happened. 16-20 You cast gust of wind. |\n| 21-25 | You cast detect thoughts on the target you chose. If you didn't target a creature, you instead take 1d6 psychic damage. |\n| 26-30 | You cast stinking cloud. |\n| 31-33 | Heavy rain falls in a 60-foot radius centered on the target. The area becomes lightly obscured. The rain falls until the start of your next turn. |\n| 34-36 | An animal appears in the unoccupied space nearest the target. The animal isn't under your control and acts as it normally would. Roll a d100 to determine which animal appears. On a 01-25, a rhinoceros appears; on a 26-50, an elephant appears; and on a 51-100, a rat appears. |\n| 37-46 | You cast lightning bolt. |\n| 47-49 | A cloud of 600 oversized butterflies fills a 30-foot radius centered on the target. The area becomes heavily obscured. The butterflies remain for 10 minutes. |\n| 50-53 | You enlarge the target as if you had cast enlarge/reduce. If the target can't be affected by that spell, or if you didn't target a creature, you become the target. |\n| 54-58 | You cast darkness. |\n| 59-62 | Grass grows on the ground in a 60-foot radius centered on the target. If grass is already there, it grows to ten times its normal size and remains overgrown for 1 minute. |\n| 63-65 | An object of the GM's choice disappears into the Ethereal Plane. The object must be neither worn nor carried, within 120 feet of the target, and no larger than 10 feet in any dimension. |\n| 66-69 | You shrink yourself as if you had cast enlarge/reduce on yourself. |\n| 70-79 | You cast fireball. |\n| 80-84 | You cast invisibility on yourself. |\n| 85-87 | Leaves grow from the target. If you chose a point in space as the target, leaves sprout from the creature nearest to that point. Unless they are picked off, the leaves turn brown and fall off after 24 hours. |\n| 88-90 | A stream of 1d4 × 10 gems, each worth 1 gp, shoots from the wand's tip in a line 30 feet long and 5 feet wide. Each gem deals 1 bludgeoning damage, and the total damage of the gems is divided equally among all creatures in the line. |\n| 91-95 | A burst of colorful shimmering light extends from you in a 30-foot radius. You and each creature in the area that can see must succeed on a DC 15 Constitution saving throw or become blinded for 1 minute. A creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. |\n| 96-97 | The target's skin turns bright blue for 1d10 days. If you chose a point in space, the creature nearest to that point is affected. |\n| 98-100 | If you targeted a creature, it must make a DC 15 Constitution saving throw. If you didn't target a creature, you become the target and must make the saving throw. If the saving throw fails by 5 or more, the target is instantly petrified. On any other failed save, the target is restrained and begins to turn to stone. While restrained in this way, the target must repeat the saving throw at the end of its next turn, becoming petrified on a failure or ending the effect on a success. The petrification lasts until the target is freed by the greater restoration spell or similar magic. |", null));
	}
}
